;; curriculum: Algebra-1 (gr 9) — linear functions, slope; prerequisites: plain
;; math target: slope = rise ÷ run; a linear function climbs at a constant rate.

app riya-level-ramp "1.1.0"
"riya level 2 · The Ramp — slope is rate. Four beats: slope ½ stairs, steeper slope 1 stairs, a negative-slope glide, then a fork where speed decides the path. Catch 4 ★ and the tuning pad. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas with slope-tinted curves and angle arcs. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaRampOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaRampBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaRampPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaRampFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaRampFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }
  type RiyaRampPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaRampCurveSample = {
    x : number!
    y : number!
  }
  type RiyaRampCurve = {
    label : string
    color : string
    samples : [RiyaRampCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaRampGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaRampAngle = {
    x : number!
    y : number!
    from : number!
    to : number!
    color : string
    label : string
  }

  entity RiyaRampState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaRampBody = { x: -9, y: 1.5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaRampPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaRampFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "ramp"
    platforms : [RiyaRampPlatform] = []
    curves : [RiyaRampCurve] = []
    guides : [RiyaRampGuide] = []
    angles : [RiyaRampAngle] = []
  }

  entity RampTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait RampBody = Body.traits.PlatformerBody -> RiyaRampState {
    events {
      STEER: RAMP_STEER
      JUMP: RAMP_LEAP
      PLACE: RAMP_PLACE
      RESTART: RAMP_RESTART
      SET_TUNING: RAMP_SET_TUNING
      SET_PLATFORMS: RAMP_SET_PLATFORMS
      SET_SKATE_CURVE: RAMP_SET_SKATE_CURVE
      BODY_MOVED: RAMP_MOVED
      BODY_JUMPED: RAMP_JUMPED
      BODY_LANDED: RAMP_LANDED
      BODY_HAZARD: RAMP_HAZARD
      BODY_GOAL: RAMP_GOAL
      BODY_FELL: RAMP_FELL
      BODY_SKATE_START: RAMP_SKATE_ON
      BODY_SKATE_END: RAMP_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 1.5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }
  }

  trait RampGate = Gate.traits.ObjectiveFlow -> RiyaRampState {
    events {
      PROGRESS: RAMP_PROGRESS
      GAME_END: RAMP_GAME_END
      RESTART: RAMP_RESTART
    }
    config { running: true }
  }

  trait RampFx = Particles.traits.FxParticles -> RiyaRampState {
    events {
      BURST: RAMP_BURST
    }
    config { running: true }
  }

  trait RampTutorialPreview -> RampTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait RampTutorial = Tutorial.traits.TutorialOverlay -> RampTutorialData {
    events {
      SHOW: RAMP_TUTORIAL_SHOW
      TUTORIAL_DONE: RAMP_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.RampTutorialPreview
      steps: [
        { id: "intro", title: "The Ramp", body: "Each staircase is a line with its own slope. Skate the curves, collect ★, grab the ⚡ tuning pad to feel speed as slope." }
      ]
    }
  }

  trait RampPickup = Pickup.traits.Pickup -> RiyaRampState {
    events {
      PICKED: RAMP_PICKED
      COLLECT: RAMP_COLLECT
      PICKUP_SET_COMPLETED: RAMP_PICKUP_SET_COMPLETED
      SET_FEATURES: RAMP_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait RampLevelData -> @rebindable RiyaRampState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "ramp"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          angles: (array/map @config.angles (fn a @a))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaRampPlatform]!
        stars : [RiyaRampPickup]!
        skateCurve : [RiyaRampCurveSample]
        curveOverlay : [RiyaRampCurve]
        guides : [RiyaRampGuide]
        angles : [RiyaRampAngle]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Ramp"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = mx + b"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "slope = rise ÷ run = velocity; steeper climbs faster, negative slopes speed descent"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#4ade80"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 1
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 11
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaRampPlatform] = [
        { id: "s0", x: -10, y: -2, width: 2, height: 3, type: "ground" }
        { id: "s1", x: -8, y: -2, width: 2, height: 4, type: "ground" }
        { id: "s2", x: -6, y: -2, width: 2, height: 5, type: "ground" }
        { id: "s3", x: -4, y: -2, width: 2, height: 6, type: "ground" }
        { id: "s4", x: -2, y: -2, width: 2, height: 7, type: "ground" }
        { id: "s5", x: 0, y: -2, width: 2, height: 9, type: "ground" }
        { id: "s6", x: 2, y: -2, width: 2, height: 11, type: "ground" }
        { id: "s7", x: 4, y: -2, width: 2, height: 13, type: "ground" }
        { id: "f1", x: 8.5, y: 9, width: 1, height: 0.4, type: "platform" }
        { id: "f2", x: 8.5, y: 6, width: 1, height: 0.4, type: "platform" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. Staircase beats 1–2, fork platforms beat 4; beat 3 is the skateCurve ramp."
        @tier "domain"
      stars : [RiyaRampPickup] = [
        { id: "s1", x: -5, y: 3.5, kind: "star", glyph: "★", message: "" }
        { id: "s2", x: 1, y: 7.5, kind: "star", glyph: "★", message: "" }
        { id: "s3", x: 7, y: 8.2, kind: "star", glyph: "★", message: "" }
