  }

  trait RampChallenge -> @rebindable RiyaRampState [game-core, instance] {
    initial: idle

    state idle {
      RAMP_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "tuning")
          (do
            (emit RAMP_SET_TUNING { moveSpeed: 8 })
            (emit RAMP_BURST { particles: (array/concat
              { id: "narrative-tuning-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 1.8), y: 0, message: "m × 2", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              { id: "narrative-tuning-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.3), y: 0, message: "speed = slope", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            ) }))
          null)
    }

    emits {
      RAMP_SET_TUNING -> external {
        jumpStrength : number
        moveSpeed : number
        gravity : number
      }
        @description "Renamed SET_TUNING consumed by this world's platformer-body authority; the tuning pad boosts moveSpeed."
        @tier "domain"
      RAMP_BURST -> external {
        particles : [RiyaRampFx]
      }
        @description "Particle batch spawned on the tuning-pad narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      RAMP_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "ramp"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaRampClear -> @rebindable RiyaRampState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "RAMP_NEXT", variant: "primary" } ]
        })

      RAMP_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      RAMP_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-ramp"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Ramp clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "Slope is speed — rise over run, in every direction."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-ramp" as RiyaRampPage -> RampLevelData, RampBody, RampGate, RampFx, RampPickup, RampTutorial, RiyaRampGenre, RiyaRampPlay, RampChallenge, RiyaRampClear
}
